package com.bank.upsert.db;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Models a table with a UNIQUE (account_id, day) primary key.
public class ConstraintStore {
    private static final Logger log = Logger.getLogger(ConstraintStore.class.getName());
    private final Map<String, BigDecimal> rows = new HashMap<>();   // key = account|day

    private String key(String acct, String day) { return acct + "|" + day; }

    public boolean exists(String acct, String day) { return rows.containsKey(key(acct, day)); }

    // Naive INSERT: throws if the key already exists (unique violation).
    public void insert(String acct, String day, BigDecimal amount) {
        String k = key(acct, day);
        if (rows.containsKey(k)) throw new IllegalStateException("duplicate key: " + k);
        rows.put(k, amount);
        log.info(() -> "INSERT " + k + " total=" + amount);
    }

    // Atomic UPSERT: insert or add to existing total — never throws on conflict.
    public synchronized void upsertAdd(String acct, String day, BigDecimal amount) {
        String k = key(acct, day);
        rows.merge(k, amount, BigDecimal::add);      // insert-or-update in one atomic step
        log.info(() -> "UPSERT " + k + " total=" + rows.get(k));
    }

    public BigDecimal total(String acct, String day) { return rows.get(key(acct, day)); }
}
