package com.bank.upsert.service;

import com.bank.upsert.db.ConstraintStore;
import java.math.BigDecimal;
import java.util.logging.*;

public class DailyTotalService {
    private static final Logger log = Logger.getLogger(DailyTotalService.class.getName());

    // NAIVE: check-then-act — racey under concurrency.
    public void naiveAdd(ConstraintStore db, String acct, String day, BigDecimal amount) {
        try {
            if (!db.exists(acct, day)) db.insert(acct, day, amount);   // window for a race
            // (an UPDATE branch would go here)
        } catch (RuntimeException ex) {
            log.log(Level.SEVERE, "naive path failed (duplicate key race)", ex);
        }
    }

    // SAFE: single atomic UPSERT.
    public void safeAdd(ConstraintStore db, String acct, String day, BigDecimal amount) {
        db.upsertAdd(acct, day, amount);
    }
}
