package com.bank.upsert;

import com.bank.upsert.db.ConstraintStore;
import com.bank.upsert.service.DailyTotalService;
import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class UpsertDemo {
    private static final Logger log = Logger.getLogger(UpsertDemo.class.getName());

    public static void main(String[] args) throws Exception {
        setupLogger();
        DailyTotalService svc = new DailyTotalService();

        log.info("=== Naive path under concurrency (duplicate-key race) ===");
        ConstraintStore db1 = new ConstraintStore();
        runConcurrent(() -> svc.naiveAdd(db1, "SAV2001", "2026-10-25", new BigDecimal("50000")));

        log.info("=== Safe UPSERT path under concurrency ===");
        ConstraintStore db2 = new ConstraintStore();
        runConcurrent(() -> svc.safeAdd(db2, "SAV2001", "2026-10-25", new BigDecimal("50000")));
        log.info(() -> "UPSERT final total = " + db2.total("SAV2001", "2026-10-25"));
    }

    private static void runConcurrent(Runnable task) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        CountDownLatch gate = new CountDownLatch(1);
        for (int i = 0; i < 4; i++) pool.submit(() -> { try { gate.await(); } catch (InterruptedException e) {} task.run(); });
        gate.countDown();
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

